scripts.script:
if (args.move.type === 'basic') {
    // 将武器原本的伤害再次叠加到总伤害中，实现翻倍
    const weaponDmg = args.baseData.weapon || 0;
    args.output.damage += weaponDmg;
    args.output.bonusDesc.push(`武器伤害翻倍 (+${weaponDmg})`);
}

if (args.move.type === 'basic' && args.isHit) {
    const targetStance = args.target.system.martial?.stanceActive;
    if (!targetStance) {
        const msg = `<div class="xjzl-chat-card"><div style="padding:5px; border-left:4px solid #f39c12; background:rgba(243,156,18,0.1); margin-left:2px;"><div style="font-weight:bold; color:#d68910; font-size:1.1em;"><i class="fas fa-angle-double-right"></i> 强力击退！</div><div style="font-size:0.9em; margin-top:3px; color:#555;"><b>${args.target.name}</b> 失去平衡，被击退 <b>1 米</b>！</div></div></div>`;
        ChatMessage.create({
            content: msg,
            speaker: ChatMessage.getSpeaker({actor: actor})
        });
    }
}

if (args.move.type === 'basic' && args.isHit) {
    // 如果需要修改流失伤害数值，请修改下方 amount 的值
    await args.target.applyDamage({ amount: 5, type: 'liushi', attacker: actor });
    actor.showFloatyText('致伤流血', { fill: '#8b0000' });
}

if (args.move.type === 'basic') {
    const spd = actor.system.combat.speedTotal || 0;
    if (spd > 0) {
        args.output.damage += spd;
        args.output.bonusDesc.push(`速度转化伤害 (+${spd})`);
    }
}

if (args.move.type === 'basic') {
    const targetStance = args.target.system.martial?.stanceActive;
    if (!targetStance) {
        // 将暴击阈值大幅降低(通过正数修改)，保证只要命中必定触发暴击
        args.flags.critThresholdMod += 20;
    }
}

if (args.move.type === 'basic') {
    // 如需修改减免数值，请修改下方的 5
    const reduceAmount = 5;
    args.output.damage = Math.max(0, args.output.damage - reduceAmount);
    actor.showFloatyText(`武器格挡 -${reduceAmount}`, { fill: '#cccccc' });
}

if (args.move.type === 'basic') {
    const shuxie = actor.system.arts.shuxie?.total || 0;
    const zuohua = actor.system.arts.zuohua?.total || 0;
    const totalBonus = shuxie + zuohua;
    if (totalBonus > 0) {
        args.output.damage += totalBonus;
        args.output.bonusDesc.push(`文墨化武 (+${totalBonus})`);
    }
}

if (args.move.type === 'basic') {
    // 暴击阈值修正，正数表示更容易暴击(阈值下降)
    args.flags.critThresholdMod += 1;
}

if (args.move.type === 'basic' && args.isHit) {
    const targetStance = args.target.system.martial?.stanceActive;
    if (!targetStance) {
        const msg = `<div class="xjzl-chat-card"><div style="padding:5px; border-left:4px solid #e74c3c; background:rgba(231,76,60,0.1); margin-left:2px;"><div style="font-weight:bold; color:#c0392b; font-size:1.1em;"><i class="fas fa-space-shuttle" style="transform:rotate(-45deg);"></i> 腾空击飞！</div><div style="font-size:0.9em; margin-top:3px; color:#555;"><b>${args.target.name}</b> 遭到重击，被击飞 <b>1 米</b>！</div></div></div>`;
        ChatMessage.create({
            content: msg,
            speaker: ChatMessage.getSpeaker({actor: actor})
        });
    }
}

if (args.move.type === 'basic') {
    // 如需修改命中数值，请修改下方的 5
    args.flags.bonusHit += 5;
}

// 如果是纯普通攻击（不包括趁虚而入），则不生效
if (args.move.type === 'basic' && args.move.id !== 'opportunity-attack') return;

const yanzou = actor.system.arts.yanzou?.total || 0;
if (yanzou > 0) {
    args.flags.bonusHit += yanzou;
}

// 配置区：请在此处修改数值和类型
// 类型支持: waigong, neigong, poison, fire, bleed, mental, liushi
const extraAmount = 10;
const extraType = 'fire'; 

if (args.isHit) {
    await args.target.applyDamage({ amount: extraAmount, type: extraType, attacker: actor });
    actor.showFloatyText(`附加 ${game.i18n.localize(CONFIG.XJZL.damageTypes[extraType])}`, { fill: '#ff4500' });
}

// 修改乘数请更改下方的 2
const multiplier = 2;
const original = args.output.damage;
args.output.damage *= multiplier;
args.output.bonusDesc.push(`致命打击 (面板伤害 x${multiplier})`);

// 请在这里修改固定增加的伤害数值
const bonus = 10;
args.output.damage += bonus;
args.output.bonusDesc.push(`额外固定增伤 (+${bonus})`);

// 将最终计算出来的理论伤害减半
args.output.damage = Math.floor(args.output.damage / 2);
actor.showFloatyText('伤害减半', { fill: '#3498db' });

// 强制将暴击状态设为 false，使其按照普通命中计算
if (args.config.isCrit) {
    args.config.isCrit = false;
    actor.showFloatyText('免疫暴击', { fill: '#9b59b6' });
}

// 开启系统底层的被动格挡标记，无需手动开启架招
// 注意：必须写 actor.xjzlStatuses（Document 上的对象），S 指向 system DataModel，写 S.xjzlStatuses 不会被读取
actor.xjzlStatuses.passiveBlock = true;

// 请在这里修改希望降低的暴击阈值（正数表示门槛下降，更容易暴击）
const mod = 10;
args.flags.critThresholdMod += mod;

if (args.isHit) {
    const status = CONFIG.statusEffects.find(e => e.id === 'prone');
    if (status) {
        // 克隆系统状态以安全应用
        const effectData = foundry.utils.deepClone(status);
        effectData.origin = thisItem?.uuid || actor.uuid;
        await game.xjzl.api.effects.addEffect(args.target, effectData);
        actor.showFloatyText('击倒！', { fill: '#f1c40f' });
    }
}

// 请在此处修改每回合受到的伤害数值
const damageAmount = 10;

// 极简调用：系统底层会自动处理防御豁免规则，并发送伤害卡片
await actor.applyDamage({
    amount: damageAmount,
    type: 'poison',       // 伤害类型
    attacker: actor,     // 伤害来源指向自己
    isHit: true,         // 状态伤害必定命中
    source: 'dot'        // 明确标识伤害来源为 DOT
});

if (args.damageResult && args.damageResult.isDying) {
    await actor.applyHealing({ healer: actor,  amount: 30, type: "hp" });
    ui.notifications.info("击敌濒死，士气大振，回复30气血！");
}
